package br.com.tst.service;
import java.time.*;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
@Service
public class EntregaEpiService {
 private final JdbcTemplate jdbc;public EntregaEpiService(JdbcTemplate j){jdbc=j;}
 public record Item(Long id,Long epiId,Integer ca,String nome,LocalDate vencimento,Instant encerradoEm,String motivoEncerramento){}
 public record Entrega(Long id,Long funcionarioId,String funcionarioNome,LocalDate dataEntrega,Long responsavelId,List<Item> itens,String fichaNome){}
 private void data(LocalDate d){if(d==null||d.isAfter(LocalDate.now(ZoneId.of("America/Sao_Paulo"))))throw new IllegalArgumentException("Informe uma data de operação válida, sem data futura.");}
 private void lock(List<Long> ids){for(Long id:new TreeSet<>(ids)){if(jdbc.queryForList("select id from epis where id=? for update",Long.class,id).isEmpty())throw new RegistroNaoEncontradoException("Objeto não encontrado.");}}
 private void disponivel(Long id,LocalDate d){var e=jdbc.queryForMap("select substituido,descartado_em,vencimento from epis where id=?",id);if(Boolean.TRUE.equals(e.get("substituido"))||e.get("descartado_em")!=null||((java.sql.Date)e.get("vencimento")).toLocalDate().isBefore(d)||jdbc.queryForObject("select count(*) from entrega_epi_itens where epi_id=? and encerrado_em is null",Integer.class,id)>0)throw new IllegalArgumentException("Objeto indisponível para entrega.");}
 private void ordem(Long epi,LocalDate d){var dates=jdbc.queryForList("select d.data_entrega from entrega_epi_itens i join entregas_epi d on d.id=i.entrega_id where i.epi_id=? and i.encerrado_em is null",java.sql.Date.class,epi);if(dates.stream().filter(Objects::nonNull).anyMatch(x->x.toLocalDate().isAfter(d)))throw new IllegalArgumentException("A operação não pode ocorrer antes da entrega.");}
 private void funcionarioAtivo(Long id){var estados=jdbc.queryForList("select status from funcionarios where id=? for share",String.class,id);if(estados.isEmpty()||"In".equals(estados.getFirst()))throw new IllegalArgumentException("Funcionário inexistente ou inativo.");}
 private Long header(Long funcionario,LocalDate data,Long ator){return jdbc.queryForObject("insert into entregas_epi(funcionario_id,data_entrega,criada_em,responsavel_id) values(?,?,CURRENT_TIMESTAMP,?) returning id",Long.class,funcionario,data,ator);}
 @Transactional public Entrega entregar(Long funcionario,LocalDate data,List<Long> ids,Long ator,FichaEntrega ficha){data(data);if(ids==null||ids.isEmpty()||new HashSet<>(ids).size()!=ids.size())throw new IllegalArgumentException("Selecione objetos físicos distintos.");funcionarioAtivo(funcionario);lock(ids);for(var id:ids)disponivel(id,data);Long h=header(funcionario,data,ator);if(ficha!=null)jdbc.update("insert into fichas_entrega_epi(entrega_id,nome,conteudo) values(?,?,?)",h,ficha.nome(),ficha.conteudo());for(var id:ids)jdbc.update("insert into entrega_epi_itens(entrega_id,epi_id) values(?,?)",h,id);return buscar(h);}
 @Transactional public Entrega substituir(Long anterior,Long novo,String motivo,LocalDate data,Long ator){data(data);if(anterior.equals(novo))throw new IllegalArgumentException("Selecione outro objeto físico.");lock(List.of(anterior,novo));disponivel(novo,data);ordem(anterior,data);var rows=jdbc.queryForList("select i.id,d.funcionario_id from entrega_epi_itens i join entregas_epi d on d.id=i.entrega_id where i.epi_id=? and i.encerrado_em is null",anterior);if(rows.size()!=1)throw new IllegalArgumentException("O objeto anterior não possui entrega aberta.");var old=rows.getFirst();Long oldId=((Number)old.get("id")).longValue();Long func=((Number)old.get("funcionario_id")).longValue();funcionarioAtivo(func);jdbc.update("update entrega_epi_itens set encerrado_em=CURRENT_TIMESTAMP,motivo_encerramento=?,encerrado_por_id=? where id=?", "SUBSTITUICAO: "+motivo.trim(),ator,oldId);jdbc.update("update epis set substituido=true where id=?",anterior);Long h=header(func,data,ator);jdbc.update("insert into entrega_epi_itens(entrega_id,epi_id,item_anterior_id)values(?,?,?)",h,novo,oldId);return buscar(h);}
 @Transactional public void descartar(Long epi,String motivo,LocalDate data,Long ator){data(data);lock(List.of(epi));ordem(epi,data);if(jdbc.queryForObject("select count(*) from epis where id=? and descartado_em is not null",Integer.class,epi)>0)throw new IllegalArgumentException("Objeto já descartado.");jdbc.update("update entrega_epi_itens set encerrado_em=CURRENT_TIMESTAMP,motivo_encerramento=?,encerrado_por_id=? where epi_id=? and encerrado_em is null","DESCARTE: "+motivo.trim(),ator,epi);jdbc.update("update epis set descartado_em=CURRENT_TIMESTAMP,data_descarte=?,motivo_descarte=?,responsavel_descarte_id=? where id=?",data,motivo.trim(),ator,epi);}
 @Transactional(readOnly=true)public Entrega buscar(Long id){var rows=jdbc.queryForList("select e.funcionario_id,e.data_entrega,e.responsavel_id,f.nome funcionario_nome,arquivo.nome ficha_nome from entregas_epi e join funcionarios f on f.id=e.funcionario_id left join fichas_entrega_epi arquivo on arquivo.entrega_id=e.id where e.id=?",id);if(rows.isEmpty())throw new RegistroNaoEncontradoException("Entrega não encontrada.");var r=rows.getFirst();var items=jdbc.query("select i.*,e.ca,e.nome,e.vencimento from entrega_epi_itens i join epis e on e.id=i.epi_id where entrega_id=? order by i.id",(rs,n)->new Item(rs.getLong("id"),rs.getLong("epi_id"),rs.getInt("ca"),rs.getString("nome"),rs.getDate("vencimento").toLocalDate(),rs.getTimestamp("encerrado_em")==null?null:rs.getTimestamp("encerrado_em").toInstant(),rs.getString("motivo_encerramento")),id);return new Entrega(id,((Number)r.get("funcionario_id")).longValue(),r.get("funcionario_nome").toString(),r.get("data_entrega")==null?null:((java.sql.Date)r.get("data_entrega")).toLocalDate(),r.get("responsavel_id")==null?null:((Number)r.get("responsavel_id")).longValue(),items,(String)r.get("ficha_nome"));}
 @Transactional(readOnly=true)public List<Entrega> listar(Long funcionario){var ids=funcionario==null?jdbc.queryForList("select id from entregas_epi order by id desc limit 200",Long.class):jdbc.queryForList("select id from entregas_epi where funcionario_id=? order by id desc limit 200",Long.class,funcionario);return ids.stream().map(this::buscar).toList();}
}
